+    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
+
+    private ElementReference _scrollContainer;
+    private ElementReference _sentinel;
+    private IJSObjectReference? _module;
+    private DotNetObjectReference<MessageList>? _dotNetRef;
+    private bool _loadingMore;
+    private bool _observerAttached;
+
+    private int GetReplyCount(int messageId) =>
+        ReplyCountMap.TryGetValue(messageId, out var count) ? count : 0;
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            _dotNetRef = DotNetObjectReference.Create(this);
+            _module = await JS.InvokeAsync<IJSObjectReference>("import",
+                "./_content/sv-5691e24a3d984f678237bdfd8373d13c/Components/Pages/Chat/MessageList.razor.js");
+        }
+
+        if (HasMore && !_observerAttached && _module is not null)
+        {
+            try
+            {
+                await _module.InvokeVoidAsync("observeSentinel", _sentinel, _dotNetRef);
+                _observerAttached = true;
+            }
+            catch (JSException) { /* sentinel not yet rendered */ }
+        }
+    }
+
+    [JSInvokable]
+    public async Task OnSentinelVisible()
+    {
+        if (_loadingMore) return;
+        _loadingMore = true;
+        _observerAttached = false;
+        StateHasChanged();
+
+        await OnLoadMore.InvokeAsync();
+
+        _loadingMore = false;
+        StateHasChanged();
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (_module is not null)
+        {
+            try { await _module.InvokeVoidAsync("disconnect"); } catch { }
+            await _module.DisposeAsync();
+        }
+        _dotNetRef?.Dispose();
+    }
