@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_5691e24a3d984f678237bdfd8373d13c.Models
@using sv_5691e24a3d984f678237bdfd8373d13c.Components.Layout
@inject IChatService ChatService
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="panel-sidebar">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="panel-main @(_threadOpen ? "" : "panel-main-full")">
        @if (_selectedChannel is not null)
        {
            <div class="main-header">
                <h3># @_selectedChannel.Name</h3>
                <span class="main-header-desc">@_selectedChannel.Description</span>
            </div>

            <MessageList Messages="_messages"
                         ReplyCountMap="_replyCountMap"
                         HasMore="_hasMoreMessages"
                         OnLoadMore="LoadOlderMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction" />

            <MessageInput Placeholder="@($"Message #{_selectedChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="panel-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnSendReply="SendThreadReply"
                         OnClose="CloseThread" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    private bool _threadOpen;
    private int _activeThreadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private Dictionary<int, int> _replyCountMap = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();

        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _hasMoreMessages = true;
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count >= PageSize;
        BuildReplyCountMap();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (!_hasMoreMessages || _selectedChannel is null) return;

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize) _hasMoreMessages = false;

        _messages.InsertRange(0, older);
        BuildReplyCountMap();
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _activeThreadRootId = messageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);

        if (_threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(messageId);
        // Thread includes root message; replies are all except the root
        _threadReplies = thread.Where(m => m.Id != messageId).ToList();
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        _activeThreadRootId = 0;
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _activeThreadRootId == 0) return;

        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _activeThreadRootId);
        _threadReplies.Add(reply);
        BuildReplyCountMap();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update: find and update the message in the local list
        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("You"))
                {
                    reactions[existing] = r with { Users = [..r.Users, "You"] };
                }
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[idx] = msg with { Reactions = reactions };
        }
    }

    private void BuildReplyCountMap()
    {
        _replyCountMap = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        // Also count thread replies if thread is open
        if (_threadOpen && _activeThreadRootId > 0)
        {
            _replyCountMap[_activeThreadRootId] = _threadReplies.Count;
        }
    }

    public ValueTask DisposeAsync() => ValueTask.CompletedTask;
}

