toolArgs.file_text:
.chat-container {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.panel-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.panel-main {
    flex: 55;
    min-width: 0;
    display: flex;
    flex-direction: column;
    background: #fff;
    overflow: hidden;
}

.panel-main-full {
    flex: 80;
}

.panel-thread {
    flex: 0 0 25%;
    min-width: 280px;
    max-width: 420px;
}

.main-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.main-header h3 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #2e3338;
}

.main-header-desc {
    font-size: 0.8rem;
    color: #72767d;
    margin-top: 2px;
    display: block;
}

.no-channel {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #72767d;
    font-size: 1.1rem;
}

